            raise RunnerError(f"FFN-output component input mismatch: {name}")
        twin = TWINS[name]
        if not twin.is_file() or twin.stat().st_size != size or base.sha256_file(twin) != digest:
            raise RunnerError(f"FFN-output component twin mismatch: {name}")
